@section('content')<div class="container-fluid px-3 px-lg-4 py-4"><div class="d-flex justify-content-between align-items-end mb-4"><div><p class="eyebrow mb-2">WMS / ISSUE</p><h1 class="h3 mb-2">สร้างใบเบิกสินค้า</h1><p class="text-secondary mb-0">เอกสารใช้หน่วย Stock ของสินค้า และจะตัด Stock เมื่อกดลง Stock</p></div><a class="btn btn-outline-secondary" href="{{ route('wms.issues.index') }}">← กลับ</a></div><div class="card border-0 shadow-sm"><div class="card-body p-4"><form id="issue-form" method="post" action="{{ route('wms.issues.store') }}">@csrf<div class="row g-3 mb-4"><div class="col-md-3"><label class="form-label">วันที่เอกสาร</label><input class="form-control" type="date" name="document_date" value="{{ now()->format('Y-m-d') }}" required></div><div class="col-md-3"><label class="form-label">ประเภทการเบิก</label><select class="form-select" name="issue_type" required><option value="GENERAL">เบิกทั่วไป</option><option value="PRODUCTION">เบิกเข้าผลิต</option><option value="PROJECT">เบิกโครงการ</option></select></div><div class="col-md-6"><label class="form-label">เหตุผล</label><input class="form-control" name="reason" minlength="5" maxlength="500" placeholder="ระบุเหตุผลการเบิก" required></div></div><div class="d-flex justify-content-between align-items-center mb-2"><h2 class="h5 mb-0">รายการเบิก</h2><button type="button" class="btn btn-sm btn-app-soft" id="add-line">+ เพิ่มรายการ</button></div><div class="table-responsive"><table class="table align-middle" id="issue-lines"><thead><tr><th style="min-width:320px">สินค้า</th><th style="min-width:190px">หน่วย Stock</th><th style="min-width:170px" class="text-end">คงเหลือพร้อมใช้</th><th style="min-width:180px" class="text-end">จำนวนเบิก</th><th style="width:60px">จัดการ</th></tr></thead><tbody><tr><td><select class="form-select js-item" name="lines[0][item_id]" required><option value="">ค้นหาสินค้า</option></select></td><td><select class="form-select js-uom" name="lines[0][uom_id]" required><option value="">หน่วย Stock</option></select></td><td class="text-end"><span class="js-available text-secondary">เลือกสินค้า</span></td><td><input class="form-control text-end" type="number" name="lines[0][quantity]" min="0.00000001" step="any" required></td><td><button type="button" class="btn btn-sm btn-app-danger js-remove" title="ลบรายการ"><i class="bx bx-trash"></i></button></td></tr></tbody></table></div><div class="d-flex gap-2 mt-4"><button class="btn btn-dark" type="submit">บันทึกร่าง</button><a class="btn btn-outline-secondary" href="{{ route('wms.issues.index') }}">ยกเลิก</a></div></form></div></div></div>@endsection
@push('scripts')<script>$(function(){const configuredIssueTypes=@json(($issueTypes ?? collect())->map(fn($type)=>['code'=>$type->code,'name'=>$type->name])->values());if(configuredIssueTypes.length){const select=$('select[name="issue_type"]');select.empty();configuredIssueTypes.forEach(t=>select.append(new Option(t.name+' ('+t.code+')',t.code)));}const tb=$('#issue-lines tbody'),itemUrl='{{ route('wms.issues.item-options') }}';function syncStock(s){const d=s.select2('data')[0],r=s.closest('tr'),available=d?.available_quantity??null;r.find('.js-available').text(d?.available_label||'เลือกสินค้า').toggleClass('text-danger',available!==null&&Number(available)<0).toggleClass('text-success',available!==null&&Number(available)>0);}function init(s){window.erpInitSelect2(s,{ajax:{url:itemUrl,delay:250,data:p=>({q:p.term||'',page:p.page||1}),processResults:d=>d}});s.on('select2:select',e=>{const d=e.params.data,u=s.closest('tr').find('.js-uom');u.empty().append(new Option(d.uom_label||'หน่วย Stock',d.uom_id,true,true));syncStock(s);}).on('select2:clear',()=>s.closest('tr').find('.js-available').text('เลือกสินค้า').removeClass('text-success text-danger'));}init($('.js-item'));$('#add-line').on('click',function(){let i=tb.find('tr').length;const r=$('<tr><td><select class="form-select js-item" name="lines['+i+'][item_id]" required><option value="">ค้นหาสินค้า</option></select></td><td><select class="form-select js-uom" name="lines['+i+'][uom_id]" required><option value="">หน่วย Stock</option></select></td><td class="text-end"><span class="js-available text-secondary">เลือกสินค้า</span></td><td><input class="form-control text-end" type="number" name="lines['+i+'][quantity]" min="0.00000001" step="any" required></td><td><button type="button" class="btn btn-sm btn-app-danger js-remove" title="ลบรายการ"><i class="bx bx-trash"></i></button></td></tr>');tb.append(r);init(r.find('.js-item'));});tb.on('click','.js-remove',function(){if(tb.find('tr').length>1)$(this).closest('tr').remove();});window.erpAjaxForm({form:'#issue-form',url:$('#issue-form').attr('action'),method:'POST',redirect:true});});</script>@endpush
